// Example of a function that performs calculation
function sumNumbers(n) {
  let total = 0;
  for (let i = 1; i <= n; i++) {
    total += i;
  }
  return total;
}

// Similar: memoized function with cache
function memoizedSquare(num) {
  if (!memoizedSquare.cache) {
    memoizedSquare.cache = {};
  }
  if (memoizedSquare.cache[num] !== undefined) {
    return memoizedSquare.cache[num];
  }
  const result = num * num;
  memoizedSquare.cache[num] = result;
  return result;
}

